use hsum::domain::{ByteSpan, Citation, DocumentId, IndexId, ProjectId, SafeSlug, SourceId};
use hsum::ingest::{
    ChunkKind, ChunkSettings, QuoteBloom, SnapshotRevision, body_sha256, chunk_bytes,
